#include "ble/speedbike_link.h"
#include <NimBLEDevice.h>
#include "config/speedbike_config.h"
#include "core/byte_ring.h"
namespace { ByteRing ring; bool found=false,connected=false,disconnected=false; NimBLEAdvertisedDevice *device=nullptr; NimBLERemoteCharacteristic *writeCharacteristic=nullptr; portMUX_TYPE mux=portMUX_INITIALIZER_UNLOCKED;
class ScanCallbacks:public NimBLEScanCallbacks { void onResult(const NimBLEAdvertisedDevice *candidate) override { if(candidate->getName()==SpeedBikeConfig::DeviceName){device=const_cast<NimBLEAdvertisedDevice*>(candidate);found=true;NimBLEDevice::getScan()->stop();} } } scanCallbacks;
void notify(NimBLERemoteCharacteristic*,uint8_t *data,size_t length,bool){portENTER_CRITICAL(&mux);ring.push(data,length);portEXIT_CRITICAL(&mux);} }
void SpeedBikeLink::begin(){NimBLEDevice::init("");} void SpeedBikeLink::startScan(){NimBLEDevice::getScan()->setScanCallbacks(&scanCallbacks);NimBLEDevice::getScan()->start(0,false);} bool SpeedBikeLink::takeDeviceFound(){const bool value=found;found=false;return value;} bool SpeedBikeLink::connect(){if(!device)return false;NimBLEClient *client=NimBLEDevice::createClient();client->setConnectTimeout(5);if(!client->connect(device)){NimBLEDevice::deleteClient(client);return false;}NimBLERemoteService *service=client->getService("fff0");if(!service){client->disconnect();return false;}NimBLERemoteCharacteristic *notifyCharacteristic=service->getCharacteristic("fff1");writeCharacteristic=service->getCharacteristic("fff2");if(!notifyCharacteristic||!writeCharacteristic||!notifyCharacteristic->subscribe(true,notify)){client->disconnect();return false;}connected=true;return true;} bool SpeedBikeLink::takeConnected(){const bool value=connected;connected=false;return value;} bool SpeedBikeLink::takeDisconnected(){const bool value=disconnected;disconnected=false;return value;} bool SpeedBikeLink::popByte(uint8_t &byte){portENTER_CRITICAL(&mux);const bool value=ring.pop(byte);portEXIT_CRITICAL(&mux);return value;} bool SpeedBikeLink::write(const uint8_t *bytes,size_t length){return writeCharacteristic&&writeCharacteristic->writeValue(bytes,length,false);} 
